import time
import re
import six
from .base import EMSSInterface


class SDLManager(EMSSInterface):
    """
    EMSsim keywords related to SDLs
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(SDLManager, self).__init__()

    def wait_for_sdl(self, timeout=120, fail_no_sdl=True, dump=None, enb_id=None, bts_id=None, alias=None):
        """
        Wait for SDL.

        :param timeout: Maximum waiting time in seconds (default=120)
        :param fail_no_sdl: Assert failure if no SDL occurred (defult=True)
        :param dump: Dictionary of SDL_RECORD names with the list of SDL fields to dump
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: SDL object or None if no SDL occurred

        +---------+--------------+------------------------------------------------------------------+
        |           Examples                                                                        |
        +=========+==============+==================================================================+
        | ${sdl}= | wait_for_sdl                                                                    |
        +---------+--------------+------------------------------------------------------------------+
        | ${sdl}= | wait_for_sdl | dump={'RRC_CONNECTION':                                          |
        |         |              | ['SECTOR_ID', 'RRC_ORIGINATION_CAUSE', 'CRR',                    |
        |         |              | 'RRC_CONNECTION_RELEASE_CAUSE', 'LAST_USED_RRC_CAUSE',           |
        |         |              | 'LAST_USED_S1AP_CAUSE', 'LAST_USED_X2AP_CAUSE']}                 |
        +---------+--------------+------------------------------------------------------------------+
        """
        timeout = self._opt_int(timeout)
        fail_no_sdl = self._opt_bool(fail_no_sdl)
        dump = self._opt_dict(dump)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().subscribe_events(event_type='sdl')
        sdl = None
        self.last_sdl = None
        print("Waiting for SDL up to %s seconds" % timeout)
        start_time = time.time()
        while time.time() - start_time < timeout:
            sdl = self._get_emssim().get_events(event_type='sdl')
            if sdl:
                self.last_sdl = sdl[0]
                break
            time.sleep(1)
        self._get_emssim().unsubscribe_events(event_type='sdl')
        if fail_no_sdl:
            self._assert(sdl, "No SDL occurred")
        if self.last_sdl and dump:
            self._dump_sdl(self.last_sdl, dump)
        return sdl

    def verify_sdl_record(self, name=None, seqn=None, key=None, expected_fields_values=None, enb_id=None, bts_id=None, alias=None):
        """
        Verify SDL record.

        :param name: Name of the SDL_RECORD inside SDL_BUNDLE
        :param seqn: 1-based sequence number of the SDL_RECORD wth the same name inside SDL_BUNDLE (optional if key provided)
        :param key: Dictionary or list of dictionaries of the record field names and values to uniquely identify SDL_RECORD \
        inside SDL_BUNDLE (optional if seqn provided)
        :param expected_fields_values: Dictionary or list of dictionaries of the record field names and their expected values \
        (optional if key provided)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------+---------------------+--------+------------------------------------------------------+
        |           Examples                                                                                       |
        +====================+=====================+========+======================================================+
        | verify_sdl_record  | name=RRC_CONNECTION | seqn=1 |  expected_fields_values={'RRC_ORIGINATION_CAUSE': 4, |
        |                    |                     |        |  'RRC_CONNECTION_RELEASE_CAUSE': 18040,              |
        |                    |                     |        |  'LAST_USED_S1AP_CAUSE': 29,                         |
        |                    |                     |        |  'CRR': 54}                                          |
        +--------------------+---------------------+--------+------------------------------------------------------+
        | verify_sdl_record  | name=RRC_CONNECTION | key={'SECTOR_ID': '2', 'RRC_ORIGINATION_CAUSE': '4',          |
        |                    |                     | 'CRR': '54', 'RRC_CONNECTION_RELEASE_CAUSE': '18040',         |
        |                    |                     | 'LAST_USED_RRC_CAUSE': '0', 'LAST_USED_S1AP_CAUSE': '29',     |
        |                    |                     | 'LAST_USED_X2AP_CAUSE': '0'}                                  |
        +--------------------+---------------------+--------+------------------------------------------------------+
        """
        seqn = self._opt_int(seqn)
        key = self._opt_dict_or_list(key)
        expected_fields_values = self._opt_dict_or_list(expected_fields_values)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(name, "Wrong arguments: missing name.")
        self._assert(key or seqn, "Wrong arguments: key or seqn must be provided.")
        self._assert(key or expected_fields_values, "Wrong arguments: key or expected_fields_values must be provided.")
        self._assert(self.last_sdl, "No SDL to verify. Run wait_for_sdl first.")

        verify_all = True if isinstance(key, list) else False
        if verify_all and expected_fields_values:
            self._assert(isinstance(expected_fields_values, list), "Wrong arguments: expected_fields_value must be type of list if the key is a list")
            self._assert(len(expected_fields_values) == len(key), "Wrong arguments: expected_fields_value list must have the same size as key list")

        errors = []
        if seqn:
            errors = self._verify_sdl_record_by_seqn(name, seqn, expected_fields_values)
        elif verify_all:
            errors = self._verify_all_sdl_records_by_keys(name, key, expected_fields_values)
        else:
            errors = self._verify_sdl_record_by_key(name, key, expected_fields_values)
        self._assert(len(errors) == 0, "SDL verification failed.\n{err}".format(err="\n".join(errors)))

    def _verify_sdl_record_by_seqn(self, record_name, record_number, expected_fields_values):
        errors = []
        verified = False
        rec_num_by_name = 0
        for sdl_bundle in self.last_sdl['sdl_bundles']:
            for i, sdl_record in enumerate(sdl_bundle['sdl_records']):
                if sdl_record['NAME'] == record_name:
                    rec_num_by_name += 1
                    if record_number == rec_num_by_name:
                        verified = True
                        field_errors = self._verify_sdl_record_fields(sdl_record, expected_fields_values)
                        if len(field_errors) > 0:
                            errors.append("SDL record {recnum} verification failed. Name={name}, Number={number}, Errors:\n{err}".format(
                                recnum=i + 1, name=record_name, number=record_number, err="\n".join(field_errors)))
        if not verified:
            errors.append("SDL record verification failed. No such record: Name={name}, Number={number}".format(
                name=record_name, number=record_number))
        return errors

    def _verify_all_sdl_records_by_keys(self, record_name, keys_list, expected_fields_values_list):
        errors = []
        errors += self._verify_all_sdl_records_keys_exist(record_name, keys_list, expected_fields_values_list)
        errors += self._verify_all_sdl_records_extra_keys(record_name, keys_list, expected_fields_values_list)
        return errors

    def _verify_all_sdl_records_keys_exist(self, record_name, keys_list, expected_fields_values_list):
        errors = []
        for (k, key) in enumerate(keys_list):
            found = False
            for sdl_bundle in self.last_sdl['sdl_bundles']:
                for i, sdl_record in enumerate(sdl_bundle['sdl_records']):
                    if sdl_record['NAME'] == record_name:
                        eq = 0
                        for (k_name, k_value) in key.items():
                            rec_field = self._get_record_field(sdl_record, k_name)
                            if rec_field['VALUE'] == k_value:
                                eq += 1
                        if len(key.keys()) == eq:
                            found = True
                            if expected_fields_values_list is not None:
                                field_errors = self._verify_sdl_record_fields(sdl_record, expected_fields_values_list[k])
                                if len(field_errors) > 0:
                                    errors.append("[key={keynum}] SDL record {recnum} verification failed. Name={name}, Key={key}, Errors:\n{err}".format(
                                        keynum=k + 1, recnum=i + 1, name=record_name, key=key, err="\n".join(field_errors)))
            if not found:
                errors.append("No SDL record {name} for key={key}".format(name=record_name, key=key))
        return errors

    def _verify_all_sdl_records_extra_keys(self, record_name, keys_list, expected_fields_values_list):
        errors = []
        for sdl_bundle in self.last_sdl['sdl_bundles']:
            for i, sdl_record in enumerate(sdl_bundle['sdl_records']):
                if sdl_record['NAME'] == record_name:
                    found = False
                    for (k, key) in enumerate(keys_list):
                        eq = 0
                        for (k_name, k_value) in key.items():
                            rec_field = self._get_record_field(sdl_record, k_name)
                            if rec_field['VALUE'] == k_value:
                                eq += 1
                        if len(key.keys()) == eq:
                            found = True
                    if not found:
                        key = {}
                        for (k_name, k_value) in keys_list[0].items():
                            rec_field = self._get_record_field(sdl_record, k_name)
                            key[k_name] = rec_field['VALUE']
                        errors.append("Extra key: {key}".format(key=key))
        return errors

    def _verify_sdl_record_by_key(self, record_name, key, expected_fields_values):
        errors = []
        verified = False
        for sdl_bundle in self.last_sdl['sdl_bundles']:
            for i, sdl_record in enumerate(sdl_bundle['sdl_records']):
                if sdl_record['NAME'] == record_name:
                    eq = 0
                    for (k, v) in key.items():
                        rec_field = self._get_record_field(sdl_record, k)
                        if rec_field['VALUE'] == v:
                            eq += 1
                    if len(key.keys()) == eq:
                        verified = True
                        field_errors = self._verify_sdl_record_fields(sdl_record, expected_fields_values)
                        if len(field_errors) > 0:
                            errors.append("SDL record {recnum} verification failed. Name={name}, Key={key}, Errors:\n{err}".format(
                                recnum=i + 1, name=record_name, key=key, err="\n".join(field_errors)))
        if not verified:
            errors.append("SDL record verification failed. No such record: Name={name}, Key={key}".format(
                name=record_name, key=key))
        return errors

    def _verify_sdl_record_fields(self, sdl_record, expected_fields_values):
        errors = []
        if expected_fields_values is None:
            return errors

        for (field_name, expected_value) in expected_fields_values.items():
            sdl_field = self._get_record_field(sdl_record, field_name)
            if not sdl_field:
                errors.append("Missing SDL field: %s" % field_name)
                continue
            sdl_field_value = self._norm_value(sdl_field['VALUE'])
            if isinstance(expected_value, list):
                (vmin, vmax) = self._get_min_max(expected_value)
                if sdl_field_value > vmax:
                    errors.append("Wrong field {name} value: {value}, it is greater than expected max {exp_value}".format(
                        name=field_name, value=sdl_field_value, exp_value=vmax))
                if sdl_field_value < vmin:
                    errors.append("Wrong field {name} value: {value}, it is smaller than expected min {exp_value}".format(
                        name=field_name, value=sdl_field_value, exp_value=vmin))
            else:
                expected_value = self._norm_value(expected_value)
                if sdl_field_value != expected_value:
                    errors.append("Wrong field {name} value: {value}, expected={exp_value}".format(
                        name=field_name, value=sdl_field_value, exp_value=expected_value))
        return errors

    def _get_record_field(self, sdl_record, name):
        for field in sdl_record['sdl_fields']:
            if field['NAME'] == name:
                return field
        return {}

    def _get_min_max(self, tab):
        vmin = self._norm_value(tab[0])
        vmax = self._norm_value(tab[1])
        return (vmin, vmax)

    def _norm_value(self, value):
        if isinstance(value, six.string_types) and re.search(r"^\d+$", value):
            return int(value)
        return value

    def _dump_sdl(self, sdl, dump):
        for rec_name in dump:
            print("\nname='{name}': key=[".format(name=rec_name))
            for sdl_bundle in sdl['sdl_bundles']:
                for sdl_record in sdl_bundle['sdl_records']:
                    if sdl_record['NAME'] == rec_name:
                        print("{")
                        for field_name in dump[sdl_record['NAME']]:
                            rec_field = self._get_record_field(sdl_record, field_name)
                            print("    '%s': '%s'," % (field_name, rec_field['VALUE']))
                        print("},")
            print("]")
